package io.github.ysl_ovo.douyuplus.hooks;

import android.util.Base64;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

public class WatermelonScript {
    private static volatile String cachedScript = null;

    private static final String GZ_B64 = "";

    public static String getScript() {
        if (cachedScript != null) {
            return cachedScript;
        }
        try {
            byte[] compressed = Base64.decode(GZ_B64, Base64.DEFAULT);
            GZIPInputStream gis = new GZIPInputStream(new ByteArrayInputStream(compressed));
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int len;
            while ((len = gis.read(buf)) != -1) {
                baos.write(buf, 0, len);
            }
            gis.close();
            cachedScript = new String(baos.toByteArray(), StandardCharsets.UTF_8);
            return cachedScript;
        } catch (Throwable t) {
            return "";
        }
    }
}
